cssHead:
body {
  font-family: 'Geist', sans-serif;
  background-color: #F6F7F4;
  color: #203E35;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
}
.orb-logo {
  width: 28px;
  height: 28px;
  border-radius: 9999px;
  background: radial-gradient(circle at 35% 30%, #A2BCA9 0%, #7F9A86 55%, #597360 100%);
  box-shadow: 2px 3px 6px -1px rgba(217, 164, 65, 0.45), 0 1px 3px rgba(32, 62, 53, 0.15);
  position: relative;
}
.orb-logo::after {
  content: '';
  position: absolute;
  bottom: 2px;
  right: 2px;
  width: 11px;
  height: 11px;
  border-radius: 9999px;
  background: radial-gradient(circle, rgba(217, 164, 65, 0.7) 0%, transparent 70%);
  filter: blur(1px);
}
